import os

wiki_path = '/home/zhouhuijuan1987/wiki/youtube-video-research-wiki'
mindmap_path = 'raw/notebooklm-mindmaps/krEDel3aGGw_f5e46b39-261e-4c52-92b3-c6125973b623_20260509T015450Z_mindmap.json'

with open(os.path.join(wiki_path, mindmap_path), 'r', encoding='utf-8') as f:
    data = json.load(f)

def extract_names(node, names=None):
    if names is None:
        names = set()
    if isinstance(node, dict):
        if 'name' in node:
            names.add(node['name'])
        if 'children' in node:
            for child in node['children']:
                extract_names(child, names)
    elif isinstance(node, list):
        for item in node:
            extract_names(item, names)
    return names

concept_names = extract_names(data)
print("Extracted concept names:")
for name in sorted(concept_names):
    print(f"  {name}")"}

